mapper.select:
SELECT current_group.group_jid AS groupJid, profile.subject, profile.announce_only AS announce, profile.member_snapshot_at AS snapshotAt, NULL AS observerAccountId, COALESCE(participant.pn_jid, participant.lid_jid) AS participantJid, participant.phone, CASE WHEN participant.role IN (2, 3) THEN 1 ELSE 0 END AS admin, CASE WHEN participant.role = 3 THEN 1 ELSE 0 END AS owner, CASE participant.role WHEN 3 THEN 'owner' WHEN 2 THEN 'admin' ELSE 'member' END AS role, CASE WHEN participant.presence_status = 1 THEN 1 ELSE 0 END AS inGroup, participant.presence_source AS stateSource, participant.presence_observed_at AS stateUpdatedAt FROM wa_group current_group INNER JOIN wa_group_profile profile ON profile.tenant_id = current_group.tenant_id AND profile.group_id = current_group.id LEFT JOIN wa_group_participant participant ON participant.tenant_id = current_group.tenant_id AND participant.group_id = current_group.id WHERE current_group.tenant_id = #{tenantId} AND current_group.group_jid IN
#{groupJid}
ORDER BY current_group.group_jid ASC, COALESCE(participant.pn_jid, participant.lid_jid) ASC

SELECT COALESCE(participant.pn_jid, participant.lid_jid) AS participantJid, participant.phone, CASE WHEN participant.role IN (2, 3) THEN 1 ELSE 0 END AS admin, CASE WHEN participant.role = 3 THEN 1 ELSE 0 END AS owner, CASE participant.role WHEN 3 THEN 'owner' WHEN 2 THEN 'admin' ELSE 'member' END AS role, CASE WHEN participant.presence_status = 1 THEN 1 ELSE 0 END AS inGroup, CASE participant.presence_source WHEN 'WGP2_PROMOTE' THEN 'ROLE_EVENT' WHEN 'WGP2_DEMOTE' THEN 'ROLE_EVENT' WHEN 'GROUP_MEMBER_QUERY' THEN 'MEMBER_QUERY' WHEN 'WGP2_ADD' THEN 'ADD_EVENT' WHEN 'WGP2_LEAVE' THEN 'LEAVE_EVENT' WHEN 'WGP2_REMOVE' THEN 'REMOVE_EVENT' ELSE participant.presence_source END AS stateSource, participant.presence_observed_at AS stateUpdatedAt, participant.presence_event_id AS sourceEventId FROM wa_group current_group INNER JOIN wa_group_participant participant ON participant.tenant_id = current_group.tenant_id AND participant.group_id = current_group.id WHERE current_group.tenant_id = #{tenantId} AND current_group.group_jid = #{groupJid} AND COALESCE(participant.pn_jid, participant.lid_jid) IN
#{participantJid}
ORDER BY COALESCE(participant.pn_jid, participant.lid_jid) ASC
